const bootstrap = async (organeCritice) => { for (const nume of organeCritice) { const organ = await Registry.get(nume); if (!organ.isAlive()) { await Registry.revive(nume); await Logger.info(`Hydra: ${nume} resuscitat`); } } return true; }; const init = async () => { const critice = ['hydraCreierCoordonator', 'hydraSuprapunereOrgane', 'hydraRuteazaBeacoane']; await bootstrap(critice); await MainSystem.run(); };